		/**
		 * Processes variable definitions and returns true if the variable should be skipped
		 * @param {Variable} variable The variable to check
		 * @param {Object} def The definition of the variable
		 * @param {Scope} scope The scope containing the variable
		 * @returns {boolean} True if the variable should be skipped
		 * @private
		 */
		function processVariableDefinition(variable, def, scope) {
			const { type, name, node } = def;

			// Handle array destructuring patterns
			if (shouldProcessArrayDestructure(variable, def)) {
				return true;
			}

			// Handle class names with static initialization blocks
			if (type === "ClassName" && shouldSkipClassName(variable, def)) {
				return true;
			}

			// Handle catch variables
			if (type === "CatchClause" && shouldSkipCatchClause(variable, def)) {
				return true;
			}

			// Handle parameters
			if (type === "Parameter" && shouldSkipParameter(variable, def)) {
				return true;
			}

			// Handle regular variables
			if (shouldSkipRegularVariable(variable, def)) {
				return true;
			}

			return false;
		}

		/**
		 * Determines if array destructuring variables should be processed
		 * @param {Variable} variable The variable to check
		 * @param {Object} def The variable definition
		 * @returns {boolean} True if array destructuring should be processed
		 * @private
		 */
		function shouldProcessArrayDestructure(variable, def) {
			if (
				(config.destructuredArrayIgnorePattern &&
					def.name.parent.type === "ArrayPattern") ||
				variable.references.some(
					ref => ref.identifier.parent.type === "ArrayPattern",
				)
			) {
				if (
					config.destructuredArrayIgnorePattern &&
					config.destructuredArrayIgnorePattern.test(def.name.name)
				) {
					if (config.reportUsedIgnorePattern && isUsedVariable(variable)) {
						reportUsedIgnoredVariable(variable, "array-destructure", def.name);
					}
					return true;
				}
			}
			return false;
		}

		/**
		 * Determines if class names with static initialization blocks should be skipped
		 * @param {Variable} variable The variable to check
		 * @param {Object} def The variable definition
		 * @returns {boolean} True if class name should be skipped
		 * @private
		 */
		function shouldSkipClassName(variable, def) {
			if (
				config.ignoreClassWithStaticInitBlock &&
				def.node.body.body.some(node => node.type === "StaticBlock")
			) {
				return true;
			}
			return false;
		}

		/**
		 * Determines if catch clauses should be skipped
		 * @param {Variable} variable The variable to check
		 * @param {Object} def The variable definition
		 * @returns {boolean} True if catch clause should be skipped
		 * @private
		 */
		function shouldSkipCatchClause(variable, def) {
			if (config.caughtErrors === "none") {
				return true;
			}

			if (
				config.caughtErrorsIgnorePattern &&
				config.caughtErrorsIgnorePattern.test(def.name.name)
			) {
				if (config.reportUsedIgnorePattern && isUsedVariable(variable)) {
					reportUsedIgnoredVariable(variable, "catch-clause", def.name);
				}
				return true;
			}

			return false;
		}

		/**
		 * Determines if parameters should be skipped
		 * @param {Variable} variable The variable to check
		 * @param {Object} def The variable definition
		 * @returns {boolean} True if parameter should be skipped
		 * @private
		 */
		function shouldSkipParameter(variable, def) {
			const { node } = def;

			// Skip setter arguments
			if (
				(node.parent.type === "Property" || node.parent.type === "MethodDefinition") &&
				node.parent.kind === "set"
			) {
				return true;
			}

			// Skip all parameters if config says so
			if (config.args === "none") {
				return true;
			}

			// Skip ignored parameters
			if (
				config.argsIgnorePattern &&
				config.argsIgnorePattern.test(node.name)
			) {
				if (config.reportUsedIgnorePattern && isUsedVariable(variable)) {
					reportUsedIgnoredVariable(variable, "parameter", node);
				}
				return true;
			}

			// Skip parameters before the last used one
			if (config.args === "after-used" && !isAfterLastUsedArg(variable)) {
				return true;
			}

			return false;
		}

		/**
		 * Determines if regular variables should be skipped
		 * @param {Variable} variable The variable to check
		 * @param {Object} def The variable definition
		 * @returns {boolean} True if regular variable should be skipped
		 * @private
		 */
		function shouldSkipRegularVariable(variable, def) {
			if (
				config.varsIgnorePattern &&
				config.varsIgnorePattern.test(def.name.name)
			) {
				if (config.reportUsedIgnorePattern && isUsedVariable(variable)) {
					reportUsedIgnoredVariable(variable, "variable", def.name);
				}
				return true;
			}

			return false;
		}

		/**
		 * Reports a variable that is used but marked as ignored
		 * @param {Variable} variable The variable to report
		 * @param {VariableType} variableType The type of variable
		 * @param {ASTNode} node The node to report at
		 * @private
		 */
		function reportUsedIgnoredVariable(variable, variableType, node) {
			context.report({
				node,
				messageId: "usedIgnoredVar",
				data: getUsedIgnoredMessageData(variable, variableType),
			});
		}

 * @private
 */
function collectUnusedVariables(scope, unusedVars) {
	const variables = scope.variables;
	const childScopes = scope.childScopes;

	processCurrentScopeVariables(scope, variables, unusedVars);

	for (let i = 0; i < childScopes.length; i++) {
		collectUnusedVariables(childScopes[i], unusedVars);
	}

	return unusedVars;
}

/**
 * Processes variables of the current scope, filtering and checking for unused status.
 * @param {Object} scope The current scope.
 * @param {Variable[]} variables Variables in the current scope.
 * @param {Variable[]} unusedVars Accumulator array for unused variables.
 * @returns {void}
 * @private
 */
function processCurrentScopeVariables(scope, variables, unusedVars) {
	if (shouldProcessScopeVariables(scope)) {
		for (let i = 0; i < variables.length; i++) {
			const variable = variables[i];
			if (!isSkippableVariable(variable, scope)) {
				const def = variable.defs[0];
				if (def && isIgnoredDueToPattern(variable, def, scope)) {
					continue;
				}
				if (!isUsedVariable(variable) && !isExported(variable) && !usesExplicitResourceManagement(variable) && !hasRestSpreadSibling(variable)) {
					unusedVars.push(variable);
				}
			}
		}
	}
}

/**
 * Determines if the current scope should be processed for unused variables.
 * @param {Object} scope The scope to check.
 * @returns {boolean} True if the scope should be processed.
 * @private
 */
function shouldProcessScopeVariables(scope) {
	return scope.type !== "global" || config.vars === "all";
}

/**
 * Determines if a variable should be skipped in analysis.
 * @param {Variable} variable The variable to check.
 * @param {Object} scope The scope containing the variable.
 * @returns {boolean} True if the variable should be skipped.
 * @private
 */
function isSkippableVariable(variable, scope) {
	if (scope.type === "class" && scope.block.id === variable.identifiers[0]) {
		return true;
	}
	if (scope.functionExpressionScope) {
		return true;
	}
	if (!config.reportUsedIgnorePattern && variable.eslintUsed) {
		return true;
	}
	if (scope.type === "function" && variable.name === "arguments" && variable.identifiers.length === 0) {
		return true;
	}
	return false;
}

/**
 * Determines if a variable is ignored due to configured ignore patterns.
 * @param {Variable} variable The variable to check.
 * @param {Object} def The definition of the variable.
 * @param {Object} scope The scope containing the variable.
 * @returns {boolean} True if the variable is ignored by pattern.
 * @private
 */
function isIgnoredDueToPattern(variable, def, scope) {
	const type = def.type;

	if (
		def.name.parent.type === "ArrayPattern" ||
		variable.references.some(ref => ref.identifier.parent.type === "ArrayPattern")
	) {
		if (config.destructuredArrayIgnorePattern && config.destructuredArrayIgnorePattern.test(def.name.name)) {
			reportUsedIgnoredIfRequired(variable, "array-destructure");
			return true;
		}
	}

	if (type === "ClassName") {
		if (config.ignoreClassWithStaticInitBlock && hasStaticBlock(def.node)) {
			return true;
		}
	}

	if (type === "CatchClause") {
		if (config.caughtErrors === "none") {
			return true;
		}
		if (config.caughtErrorsIgnorePattern && config.caughtErrorsIgnorePattern.test(def.name.name)) {
			reportUsedIgnoredIfRequired(variable, "catch-clause");
			return true;
		}
	} else if (type === "Parameter") {
		if (isSetterParameter(def)) {
			return true;
		}
		if (config.args === "none") {
			return true;
		}
		if (config.argsIgnorePattern && config.argsIgnorePattern.test(def.name.name)) {
			reportUsedIgnoredIfRequired(variable, "parameter");
			return true;
		}
		if (config.args === "after-used" && astUtils.isFunction(def.name.parent) && !isAfterLastUsedArg(variable)) {
			return true;
		}
	} else if (config.varsIgnorePattern && config.varsIgnorePattern.test(def.name.name)) {
		reportUsedIgnoredIfRequired(variable, "variable");
		return true;
	}

	return false;
}

/**
 * Reports used variables that were marked with ignore patterns if reportUsedIgnorePattern is enabled.
 * @param {Variable} variable The variable to potentially report.
 * @param {VariableType} variableType The type of variable.
 * @returns {void}
 * @private
 */
function reportUsedIgnoredIfRequired(variable, variableType) {
	if (config.reportUsedIgnorePattern && isUsedVariable(variable)) {
		context.report({
			node: variable.identifiers[0].parent,
			messageId: "usedIgnoredVar",
			data: getUsedIgnoredMessageData(variable, variableType),
		});
	}
}

/**
 * Checks if a parameter is a setter parameter.
 * @param {Object} def The parameter definition.
 * @returns {boolean} True if it is a setter parameter.
 * @private
 */
function isSetterParameter(def) {
	return (
		(def.node.parent.type === "Property" || def.node.parent.type === "MethodDefinition") &&
		def.node.parent.kind === "set"
	);
}

/**
 * Checks if a class node has a static initialization block.
 * @param {ASTNode} node The class node to check.
 * @returns {boolean} True if the class has a static initialization block.
 * @private
 */
function hasStaticBlock(node) {
	return node.body.body.some(child => child.type === "StaticBlock");
}

/**
 * @fileoverview Disallow parenthesising higher precedence subexpressions.
 * @author Michael Ficarra
 * @deprecated in ESLint v8.53.0
 */
"use strict";

//------------------------------------------------------------------------------
