					pattern = config.destructuredArrayIgnorePattern;
					break;
				case "catch-clause":
					pattern = config.caughtErrorsIgnorePattern;
					break;
				case "parameter":
					pattern = config.argsIgnorePattern;
					break;
				case "variable":
					pattern = config.varsIgnorePattern;
					break;
