	it(`should error when an unexpected value is found for ${propertyName}`, async () => {
		await assertInvalidConfig(
			[
				{
					linterOptions: {
						[propertyName]: invalidValue,
					},
				},
			],
			errorMessage || /Expected one of:/u,
		);
	});

	it(`should merge two objects when second object has overrides for ${propertyName}`, () =>
		assertMergedResult(
			[
				{
					linterOptions: {
						[propertyName]: validValue1,
					},
				},
				{
					linterOptions: {
						[propertyName]: validValue2,
					},
				},
			],
			{
				plugins: baseConfig.plugins,
				linterOptions: {
					[propertyName]: 1,
				},
			},
		));

	it(`should merge an object and undefined into one object for ${propertyName}`, () =>
		assertMergedResult(
			[
				{},
				{
					linterOptions: {
						[propertyName]: validValue2,
					},
				},
			],
			{
				plugins: baseConfig.plugins,
				linterOptions: {
					[propertyName]: 1,
				},
			},
		));
}

