/**
 * Determine the dominant source of a global definition (config > inline > code)
 * @param {string} name The name of the variable
 * @param {Object} configGlobals The custom globals from config
 * @param {Object} inlineComments The global comments from inline config
 * @param {Object} codeGlobals The globals declared directly in code
 * @returns {string} One of: "config", "inline", "code", or "none"
 * @private
 */
function getGlobalDefinitionSource(name, configGlobals, inlineComments, codeGlobals) {
	if (configGlobals && Object.hasOwn(configGlobals, name)) {
		return "config";
	}
	if (
		inlineComments &&
		inlineComments.globals &&
		Object.hasOwn(inlineComments.globals, name)
	) {
		return "inline";
	}
	if (codeGlobals && Object.hasOwn(codeGlobals, name)) {
		return "code";
	}
	return "none";
}

