			const child = runESLint(ARGS_WITHOUT_CACHE);

			return assertExitCode(child, 0).then(() => {
				assert.isFalse(
					fs.existsSync(CACHE_PATH),
					"Cache file should be deleted after running ESLint without the --cache argument",
				);
			});
		});
	});

