internals.Request.prototype.getLog = function (tags, internal) {

    Hoek.assert(this.route.settings.log, 'Request logging is disabled');

    if (typeof tags === 'boolean') {
        internal = tags;
        tags = [];
    }

    tags = [].concat(tags || []);
    if (!tags.length && internal === undefined) {
        return this._logger;
    }

    const filter = tags.length ? Hoek.mapToObject(tags) : null;
    return _filterLogEvents(this._logger, filter, internal);
};

function _filterLogEvents(logger, filter, internal) {

    const result = [];

    for (let i = 0; i < logger.length; ++i) {
        const event = logger[i];

        if (!_matchesInternalFilter(event, internal)) {
            continue;
        }

        if (filter && !_matchesTagFilter(event, filter)) {
            continue;
        }

        result.push(event);
    }

    return result;
}

function _matchesInternalFilter(event, internal) {

    return internal === undefined || event.internal === internal;
}

function _matchesTagFilter(event, filter) {

    for (let j = 0; j < event.tags.length; ++j) {
        if (filter[event.tags[j]]) {
            return true;
        }
    }

    return false;
}

function getAlignmentFromElement(element: globalThis.Element): 'center' | 'end' | undefined {
  const parent = element.parentElement
  // confluence
  const alignment = parent?.dataset.align
  // note: we don't show html that confluence would parse as alignment
  // we could change that but meh
  // (they match on div.fabric-editor-block-mark with data-align)
  if (alignment === 'center' || alignment === 'end') {
    return alignment as 'center' | 'end'
  }
  if (element instanceof HTMLElement) {
    // Google docs
    const textAlign = element.style.textAlign
    if (textAlign === 'center') {
      return 'center'
    }
    // TODO: RTL things?
    if (textAlign === 'right' || textAlign === 'end') {
      return 'end'
    }
  }
}

internals.access = function (request, config, credentials, name) {

    if (!config.access) {
        return null;
    }

    const requestEntity = (credentials.user ? 'user' : 'app');

    const scopeErrors = [];
    for (let i = 0; i < config.access.length; ++i) {
        const access = config.access[i];

        // Check entity

        const entity = access.entity;
        if (entity &&
            entity !== 'any' &&
            entity !== requestEntity) {

            continue;
        }

        // Check scope

        let scope = access.scope;
        if (scope) {
            if (!credentials.scope) {
                scopeErrors.push(scope);
                continue;
            }

